-- Updates the FAQ section of the partner Guide (removes the "I can't log in." and
-- "My secure link doesn't work." rows). Source: db/guide-2026-11.md.
UPDATE reporting_platform.wiki_sections SET body_html = '<table><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Why can''t I edit a field?</td><td>The document may be Under review or Approved, a colleague may have it open, or the field comes from the Project Document or is managed by CRAF''d (for example approved budgets, standard indicators and baselines).</td></tr><tr><td>Why is Submit greyed out?</td><td>A section is not complete yet. The message next to the button names it. For reports, also tick "I authorize this report" on Overview.</td></tr><tr><td>A section won''t get its green tick.</td><td>Check the required fields, and that no text is over its word limit (the counter turns red).</td></tr><tr><td>Does CRAF''d know I''ve submitted?</td><td>Not automatically. Please email crafd@un.org after you submit.</td></tr><tr><td>I work on several projects. How do I switch?</td><td>Each project has its own box on Home, and each document is listed in the sidebar.</td></tr><tr><td>A project partner is missing from the list.</td><td>Project partners are added by CRAF''d. Contact crafd@un.org.</td></tr><tr><td>How do I change something after submitting?</td><td>Contact CRAF''d. They can send the document back to you as To revise.</td></tr><tr><td>Who do I contact for help?</td><td>The CRAF''d Secretariat at crafd@un.org. For a technical problem, include a screenshot and a short description.</td></tr></tbody></table>' WHERE slug = 'frequently-asked-questions';
